head.script:
// https://inswave01.atlassian.net/browse/WAEA-1089



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > numberMask]<br/>숫자나 통화의 포맷을 적용하기 위한 마스크 문자를 설정합니다.",
    "validation" : [
        "Column 이 inputType='text', dataType='number','float','bigDecimal' 인 경우에 numberMask 속성이 적용됩니다.",
        "Column 의 displayFormat 또는 displayFormatter 속성이 설정된 경우 numberMask 속성은 무시됩니다.",
        "String 값 설정 시, '#', '0', ',', '.' 마스크 문자를 사용하여 포맷을 설정할 수 있어야 합니다.",
        "'#' 마스크 설정 시, 해당 위치에 숫자가 있으면 표시되고 없으면 표시되지 않습니다.",
        "'0' 마스크 설정 시, 소수 영역에만 사용되며 해당 위치에 숫자가 있으면 표시되고 없으면 0 으로 표시됩니다.",
        "',', '.' 마스크 설정 시, 천단위 구분자와 소수점 위치로 표시됩니다.",
        "소수값이 있을때 마스크 문자 오른쪽에 '[round]' 를 설정하여 반올림을 적용할 수 있어야 합니다.",
        "소수값이 있을때 마스크 문자 오른쪽에 '[floor]' 를 설정하여 버림을 적용할 수 있어야 합니다.",
        "소수값이 있을때 마스크 문자 오른쪽에 '[ceil]' 를 설정하여 올림을 적용할 수 있어야 합니다.",
        "마스크 문자 설정 시, 마스크 포맷 왼쪽과 오른쪽의 일반문자는 그대로 적용됩니다.",
        "마스크 문자 설정 시, 입력값에 부호와 숫자가 아닌 값이 포함되면 'NaN' 으로 표시됩니다.",
        "미설정 시, Column 의 displayFormat, displayFormatter 속성 또는 config.xml 에 설정된 값이 적용됩니다.",
        "inputType='text', dataType='number','float','bigDecimal' 인 모든 Column 에 적용되며 Column 별로 다른 마스크를 적용하려면 Column 의 displayFormat 또는 displayFormatter 속성을 설정해야 합니다.",
        "속성값 미설정 시 config.xml 파일의 WebSquare/gridView/column[@inputType='text']/dataType[@valueType='number']/numberMask/@value 값이 적용됩니다.",
        "Column 에 displayFormat 또는 displayFormatter 가 없으면 GridView 의 numberMask 속성값이 사용됩니다.",
        "numberMask 속성은 데이터의 표시에만 포맷을 적용하며 실제 데이터값은 유지됩니다.",
        "numberMask 속성이 동작하는 조건에서 Column 의 applyFormat='all', editFormat='' 이면 Cell 이 편집 모드일때도 numberMask 속성의 포맷이 적용됩니다.",
        "numberMask 사용 시 천단위 구분자는 ',', 소수점 구분자는 '.' 이 적용됩니다.",
        "소수점 영역은 마스크 문자의 갯수만큼 표시됩니다."
    ]
}



// 검증용 원본 데이터 (number 규칙에 따라 소수 구분자는 마침표)
//  row 0 : 소수 4자리 음수  -> [round] / [floor] / [ceil] 결과 구분 (@sample 입력값)
//  row 1 : 백만 단위        -> 천단위 구분자 2회 + [ceil] 결과 구분
//  row 2 : 소수 1자리       -> 소수 마스크 '#' 생략 / '0' 채움 / 자릿수 대조
//  row 3 : 정수 2자리       -> 정수 영역 마스크 위치에 숫자가 없을때 미표시
//  row 4 : 숫자가 아닌 값   -> NaN 표시 확인
scwin.arrData = ["-1234.5678", "1234567.8912", "1234.5", "12", "12AB34"];

// Body Column 구성 (헤더 표기와 동일)
scwin.arrColumn = [
    { "id" : "col1", "desc" : "col1 (number)" },
    { "id" : "col2", "desc" : "col2 (float)" },
    { "id" : "col3", "desc" : "col3 (bigDecimal)" },
    { "id" : "col4", "desc" : "col4 (number, applyFormat=all)" },
    { "id" : "col5", "desc" : "col5 (displayFormat)" },
    { "id" : "col6", "desc" : "col6 (displayFormatter)" },
    { "id" : "col7", "desc" : "col7 (dataType=text)" },
    { "id" : "col8", "desc" : "col8 (inputType=textarea)" }
];



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적/itemset select1 은 초기 selectedIndex 미적용 -> 기본값 명시 설정 (API 가이드 @sample 마스크)
    con_numberMask.setSelectedIndex(1);

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - numberMask 는 @dynamic N 이므로 con 변경은 Target 재생성으로만 반영된다.
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vNumberMask = con_numberMask.getValue();

    // 테스트 참고 라벨 (target 생성 전, 가장 먼저 생성)
    let lbl = '';
    lbl += '[전제] Body Column 8 개 : col1 (inputType=text, dataType=number) / col2 (dataType=float) / col3 (dataType=bigDecimal) / col4 (dataType=number + applyFormat=all, editFormat 미설정) / col5 (dataType=number + displayFormat=#,##0.000) / col6 (dataType=number + displayFormatter) / col7 (dataType=text) / col8 (inputType=textarea, dataType=number)';
    lbl += '\n[전제] 8 개 Column 모두 동일한 원본 데이터 5 행 : -1234.5678 / 1234567.8912 / 1234.5 / 12 / 12AB34';
    lbl += '\n[현재] numberMask = ' + (vNumberMask === '' ? '(미설정)' : vNumberMask);
    lbl += '\n[절차] numberMask 선택 -> Target 재생성 -> [표시값 확인] 클릭 -> [원본 데이터값 확인] / [numberMask 반영값 확인] 클릭';
    lbl += '\n[확인] col1 ~ col4 의 표시값만 선택한 numberMask 포맷으로 바뀌고, col5 ~ col8 은 각자의 포맷(또는 포맷 미적용) 을 유지하는지 대조';
    lbl += '\n[확인] 편집 모드는 col1 셀과 col4 셀을 각각 더블클릭하여 편집 input 에 표시되는 값을 비교';
    $c.gcm.createLabel('label="' + lbl + '"', '', 'label1');

    // dataList 생성 (Body Column 8 개)
    let strNameSpace = $c.gcm.getNameSpace();
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    for (let i = 1; i <= 8; i++) {
        strData += '<w2:column id="col' + i + '" name="name' + i + '" dataType="text"></w2:column>';
    }
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let arrCollection = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrCollection[arrCollection.length - 1];

    let arrJson = [];
    for (let i = 0; i < scwin.arrData.length; i++) {
        arrJson.push({
            "col1" : scwin.arrData[i], "col2" : scwin.arrData[i], "col3" : scwin.arrData[i], "col4" : scwin.arrData[i],
            "col5" : scwin.arrData[i], "col6" : scwin.arrData[i], "col7" : scwin.arrData[i], "col8" : scwin.arrData[i]
        });
    }
    scwin.dlt_bind.setJSON(arrJson, false);

    // 조건 설정 (빈값은 createCList 에서 자동 제외)
    let properties = {
        numberMask : vNumberMask,
        dataList : "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:1060px;height:210px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column1" value="col1 number"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="col2 float"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column3" value="col3 bigDecimal"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column4" value="col4 applyFormat=all"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column5" value="col5 displayFormat"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column6" value="col6 displayFormatter"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column7" value="col7 dataType=text"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column8" value="col8 textarea"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // numberMask 적용 대상 (inputType=text, dataType 3 종, displayFormat/displayFormatter 없음)
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="number" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="float" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="bigDecimal" id="col3" value=""></w2:column>';
    // numberMask 적용 대상 + 편집 모드에도 포맷 적용 (applyFormat=all, editFormat 미설정)
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="number" applyFormat="all" editFormat="" id="col4" value=""></w2:column>';
    // displayFormat 설정 -> numberMask 무시
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="number" displayFormat="#,##0.000" id="col5" value=""></w2:column>';
    // displayFormatter 설정 -> numberMask 무시
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="number" displayFormatter="scwin.target1_displayFormatter" id="col6" value=""></w2:column>';
    // dataType 이 number/float/bigDecimal 이 아님 -> numberMask 미적용
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="text" id="col7" value=""></w2:column>';
    // inputType 이 text 가 아님 -> numberMask 미적용
    strTarget += '<w2:column width="130" style="" inputType="textarea" dataType="number" id="col8" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// col6 전용 displayFormatter (numberMask 보다 우선 적용되는지 대조용)
scwin.target1_displayFormatter = function (value) {
    return "[fmt]" + value;
}



// Column 의 전체 Row 표시값을 한 줄 문자열로 조합
scwin.getDisplayLine = function (colId) {
    let arrText = [];

    for (let i = 0; i < scwin.arrData.length; i++) {
        arrText.push(target1.getCellDisplayData(i, colId));
    }

    return arrText.join(" | ");
}



// 표시값 확인 (Column 별 전체 Row 의 셀 표시값)
scwin.btn_displayCheck_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    bottom.setReturnValue("numberMask : " + (con_numberMask.getValue() === "" ? "(미설정)" : con_numberMask.getValue()));

    for (let i = 0; i < scwin.arrColumn.length; i++) {
        bottom.setReturnValue(scwin.arrColumn[i].desc + " 표시값 : " + scwin.getDisplayLine(scwin.arrColumn[i].id));
    }
}



// 원본 데이터값 확인 (표시값이 바뀌어도 DataList 의 실제 데이터는 유지되는지 확인)
scwin.btn_dataCheck_onclick = function () {
    let arrValue = [];

    for (let i = 0; i < scwin.arrData.length; i++) {
        arrValue.push(dlt_bind.getCellData(i, "col1"));
    }

    wf_body_bottom.getObj("scwin").setReturnValue("col1 원본 데이터값 : " + arrValue.join(" | ") + " / col1 표시값 : " + scwin.getDisplayLine("col1"));
}



// numberMask 반영값 확인 (GridView 반영값 / config.xml 설정값)
scwin.btn_optionCheck_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let strConfig = "";

    if (typeof target1.getConfiguration === "function") {
        strConfig = target1.getConfiguration('/_wg/gridView/column[@inputType="text"]/dataType[@valueType="number"]/numberMask/@value') || "";
    }

    bottom.setReturnValue("GridView numberMask 옵션 반영값 : '" + (target1.options.numberMask || "") + "'");
    bottom.setReturnValue("config.xml numberMask 설정값 : '" + strConfig + "'");
}
